The answer is to use a directive. A directive is a way to wrap a piece of HTML and apply some behavior to it. In this case, we'll create a directive that listens to changes in the count variable and updates the overflow property accordingly.

Here's how you can do it:

1. First, create a new directive in your AngularJS app:

```javascript
angular.module('your-app', [])
  .directive('countToOverflow', function() {
    return {
      restrict: 'A',
      scope: {
        count: '=count',
        overflow: '='
      },
      template: '<div>{{count}}</div><br><span>{{overflow}}</span>',
      link: function(scope, element, attrs) {
        scope.$watch('count', function(newVal) {
          if (newVal < 100) {
            scope.overflow = "normal";
          } else if (newVal < 200) {
            scope.overflow = "warning";
          } else {
            scope.overflow = "error";
          }
        });
      }
    };
  });
```

2. Now, you can use this directive in your view:

```html
<count-to-overflow count="count" overflow="?" />
```

